const std = @import("std");

fn isPrime(n: u32) bool {
    if (n < 2) return false;
    var i: u32 = 2;
    while (i * i <= n) {
        if (@mod(n, i) == 0) return false;
        i += 1;
    }
    return true;
}

fn gcd(a: u32, b: u32) u32 {
    return if (b == 0) a else gcd(b, a % b);
}

pub fn main() !void {
    const p: u32 = 61;
    const q: u32 = 53;
    const n = p * q;
    const phi = (p - 1) * (q - 1);
    var e: u32 = 3;
    while (e < phi) {
        if (gcd(e, phi) == 1) break;
        e += 2;
    }

    std.debug.print("p={}\n", .{p});
    std.debug.print("q={}\n", .{q});
    std.debug.print("n={}\n", .{n});
    std.debug.print("phi={}\n", .{phi});
    std.debug.print("e={}\n", .{e});
    std.debug.print("isPrime(p)={}\n", .{isPrime(p)});
}

